const defaults={age:0,income:0,currentExpenses:0,savings:0,passive:0,stocks:0,stocksRate:0,money:0,moneyRate:0,'401k':0,'401kRate':0,home:0,car1:0,car2:0,car3:0,retire:0,expenses:0,socialAge:0,social:0};
const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat(I18n.locale,{style:'currency',currency:I18n.currency,maximumFractionDigits:0}).format(n);
const compact=n=>n>=1e6?I18n.currencySymbol+(n/1e6).toFixed(1)+t('m'):n>=1000?I18n.currencySymbol+Math.round(n/1000)+t('k'):money(n);
$('investments').innerHTML=[['stocks','↗','Stocks & ETFs'],['money','≋','Money market'],['401k','▥','401(k)']].map(([k,icon,title])=>`<div class="investment-row"><span class="investment-name"><span class="asset-icon">${icon}</span><span data-asset-label="${k}">${t(title)}</span></span><label class="field"><span data-currency>${I18n.currencySymbol}</span><input id="${k}" type="number" min="0" step="1000" aria-label="${t('{asset} balance',{asset:t(title)})}"></label><label class="field"><input id="${k}Rate" type="number" min="-50" max="50" step="0.1" aria-label="${t('{asset} annual return',{asset:t(title)})}"><span>%</span></label></div>`).join('');
for(const[k,v]of Object.entries(defaults))$(k).value=v;
function read(){const p={};for(const k of Object.keys(defaults)){const el=$(k);let v=Number(el.value);v=Math.min(Number(el.max||1e10),Math.max(Number(el.min||0),Number.isFinite(v)?v:0));p[k]=v;}p.age=Math.round(p.age);p.retire=Math.round(p.retire);p.socialAge=Math.round(p.socialAge);return p;}
function renderEmpty(p){
 const invested=p.stocks+p.money+p['401k'],other=p.home+p.car1+p.car2+p.car3;
 $('retire-label').textContent=p.retire;$('result-age').textContent=p.retire;
 $('countdown').textContent=t("Start by entering your plan");
 for(const id of ['retire-balance','monthly-expense','monthly-passive','affordable'])$(id).textContent=money(0);
 $('earliest').textContent='—';$('wealth').textContent=money(invested+other);$('invested').textContent=money(invested);$('other').textContent=money(other);$('wealth-ratio').style.width=(invested+other?invested/(invested+other)*100:0)+'%';
 $('runout-title').textContent=t("Your next chapter starts with a plan");$('runout-text').textContent=p.social>0&&p.socialAge<18?t("Enter your Social Security starting age to complete your projection."):t("Enter your age and retirement age to calculate your projection.");
 $('validation').textContent=p.age===0&&p.retire===0?'':p.age<18?t("Enter your current age (18 or older)."):p.retire<p.age?t("Choose a retirement age at or after your current age."):t("Enter a Social Security starting age (18 or older).");
 renderPendingCharts(p);renderAnnualCashflow(p,null);
 $('mix-subtitle').textContent=t("Annual income at retirement");
}
function renderPendingCharts(p){
 const grid=[48,106,164,222].map(y=>`<line x1="68" y1="${y}" x2="374" y2="${y}" stroke="#e4eadc"/><text x="58" y="${y+5}" text-anchor="end" fill="#738369" font-size="16">${money(0)}</text>`).join('');
 $('journey-chart').innerHTML=`<svg viewBox="0 0 400 260" role="img" aria-label="${t("Investment balance chart awaiting your plan")}"><title>${t("Investment balance chart \u2014 enter your ages to calculate a projection")}</title>${grid}<line x1="68" y1="222" x2="374" y2="222" stroke="#547d4f" stroke-width="3"/><circle cx="68" cy="222" r="5" fill="#547d4f"/><text x="68" y="250" fill="#738369" font-size="16">${t("Today")}</text><text x="374" y="250" text-anchor="end" fill="#738369" font-size="16">${t("Future")}</text><text x="221" y="120" text-anchor="middle" fill="#647659" font-size="16">${t("Enter your ages to project")}</text><text x="221" y="146" text-anchor="middle" fill="#647659" font-size="16">${t("your investment balance")}</text></svg>`;
 income(p,{expense:0,passive:0,social:0});
}
function updateInvestmentLabels(){document.querySelectorAll('[data-currency]').forEach(node=>node.textContent=I18n.currencySymbol);for(const [key,label] of [['stocks','Stocks & ETFs'],['money','Money market'],['401k','401(k)']]){document.querySelector(`[data-asset-label="${key}"]`).textContent=t(label);$(key).setAttribute('aria-label',t('{asset} balance',{asset:t(label)}));$(key+'Rate').setAttribute('aria-label',t('{asset} annual return',{asset:t(label)}));}}
function render(){updateInvestmentLabels();const p=read();
const available=p.income-p.currentExpenses;
$('cash-flow-label').textContent=available<0?t("Annual cash-flow shortfall"):t("Available to invest / year");
$('cash-flow-value').textContent=money(Math.abs(available));
$('cash-flow-value').classList.toggle('shortfall',available<0);
$('cash-flow-warning').textContent=available<0?t("Your current living expenses exceed your take-home income."):p.savings>available?t("Your annual investment amount exceeds the income left after living expenses. Check whether other funding covers the difference."):'';
if(p.age<18||p.retire<p.age||p.retire===0||(p.social>0&&p.socialAge<18)){renderEmpty(p);return;}$('retire').min=0;$('retire').max=Math.max(85,p.age);$('retire').value=p.retire;$('range-min').textContent=0;const m=FreedomModel.project(p);const r=m.rows.find(r=>r.age===p.retire);const invested=p.stocks+p.money+p['401k'];const other=p.home+p.car1+p.car2+p.car3;
$('retire-label').textContent=p.retire;$('result-age').textContent=p.retire;$('countdown').textContent=p.retire===p.age?t("Your next chapter starts today"):t('{years} years to your next chapter',{years:p.retire-p.age});$('retire-balance').textContent=money(m.retirementBalance);$('monthly-expense').textContent=money(r.expense/12);$('monthly-passive').textContent=money(r.passive/12);$('wealth').textContent=money(invested+other);$('invested').textContent=money(invested);$('other').textContent=money(other);$('wealth-ratio').style.width=(invested+other?invested/(invested+other)*100:0)+'%';
$('runout-title').textContent=m.runout===null?t("Your money lasts through age 100"):t('Investments run short at age {age}',{age:m.runout});$('runout-text').textContent=m.runout===null?t('Your spending is covered through our projection, with {amount} remaining at 100.',{amount:money(m.rows.at(-1).end)}):t('Your planned spending exceeds available income and savings {years} years into retirement.',{years:m.runout-p.retire});
$('validation').textContent=p.retire<59.5&&p['401k']>0?t("This model includes your 401(k). Early access restrictions and penalties are not modeled."):'';
let earliest=null;for(let a=p.age;a<=99;a++){if(FreedomModel.project({...p,retire:a}).runout===null){earliest=a;break;}}
$('earliest').textContent=earliest===null?t("Beyond 99"):t('Age {age}',{age:earliest});
let low=0,high=Math.max(1000000,p.expenses*2);while(FreedomModel.project({...p,expenses:high}).runout===null&&high<1e10)high*=2;
for(let i=0;i<35;i++){const mid=(low+high)/2;if(FreedomModel.project({...p,expenses:mid}).runout===null)low=mid;else high=mid;}
$('affordable').textContent=money(low/12);

journey(p,m);income(p,r);renderAnnualCashflow(p,m);
}
function journey(p,m){const W=400,H=260,L=68,R=26,T=42,B=38;const values=m.rows.map(r=>r.start);const max=Math.max(1,...values)*1.12;const x=a=>L+(a-p.age)/(100-p.age)*(W-L-R);const y=v=>H-B-v/max*(H-T-B);const points=m.rows.map((r,i)=>`${x(r.age)},${y(values[i])}`).join(' ');const area=`${L},${H-B} ${points} ${W-R},${H-B}`;let grid='';for(let i=0;i<4;i++){const val=max*i/3,yy=y(val);grid+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#edf0e6"/><text x="${L-8}" y="${yy+5}" text-anchor="end" fill="#a0aa94" font-size="16">${compact(val)}</text>`;}const ticks=[p.age,Math.round(p.age+(100-p.age)/3),Math.round(p.age+2*(100-p.age)/3),100];grid+=ticks.map(a=>`<text x="${x(a)}" y="${H-10}" text-anchor="middle" fill="#9aa58e" font-size="16">${a}</text>`).join('');$('journey-chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('Projected investment balance from age {age} to 100',{age:p.age})}"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a7c58a" stop-opacity=".35"/><stop offset="1" stop-color="#c4d7a7" stop-opacity=".03"/></linearGradient></defs>${grid}<polygon points="${area}" fill="url(#area)"/><polyline points="${points}" transform="translate(0 4)" fill="none" stroke="#c7d5b8" stroke-width="4" opacity=".5"/><polyline points="${points}" fill="none" stroke="#547d4f" stroke-width="2.5" stroke-linejoin="round"/><line x1="${x(p.retire)}" y1="${T}" x2="${x(p.retire)}" y2="${H-B}" stroke="#9aad81" stroke-dasharray="3 4"/><text x="${Math.min(W-80,x(p.retire)+8)}" y="24" font-size="16" fill="#7b9067">${t('Age {age}',{age:p.retire})}</text></svg>`;}
function income(p,r){const items=[{label:t("Investment withdrawals"),val:Math.max(0,r.expense-r.passive-r.social),color:'#547653',cls:'green'},{label:t("Passive income"),val:r.passive,color:'#a9c585',cls:'pale'},{label:t("Social Security"),val:r.social,color:'#d2b879',cls:'gold'}];const sum=items.reduce((s,i)=>s+i.val,0);let offset=0;const slices=items.map(i=>{const len=sum?i.val/sum*100:0;const s=`<circle cx="140" cy="76" r="55" fill="none" stroke="${i.color}" stroke-width="26" pathLength="100" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 140 76)"/>`;offset+=len;return s;}).join('');$('income-chart').innerHTML=`<svg viewBox="0 0 280 155" role="img" aria-label="${t("Annual retirement income sources")}"><ellipse cx="140" cy="87" rx="68" ry="66" fill="#dce3d2"/><circle cx="140" cy="76" r="55" fill="white" stroke="#eef1e7" stroke-width="26"/>${slices}<text x="140" y="76" text-anchor="middle" fill="#405d3b" font-family="Manrope,sans-serif" font-size="26" font-weight="600">${compact(sum)}</text><text x="140" y="96" text-anchor="middle" fill="#98a38b" font-size="12">${t("PER YEAR")}</text></svg>`;$('income-legend').innerHTML=items.map(i=>`<div class="income-legend-item"><span><i class="${i.cls}"></i>${i.label}</span><b>${money(i.val)}</b></div>`).join('');$('mix-subtitle').textContent=t('Annual income needed at age {age}',{age:p.retire});}
for(const k of Object.keys(defaults))$(k).addEventListener('input',render);$('reset').addEventListener('click',()=>{for(const[k,v]of Object.entries(defaults))$(k).value=v;render();});document.addEventListener('freedom-language-change',render);render();
